create or replace function public.record_sale(p_shop_id uuid,p_product_id uuid,p_quantity integer,p_sold_unit_price numeric,p_payment_method text) returns uuid language plpgsql security invoker set search_path='' as $$ declare v_product public.products; v_sale_id uuid; begin if p_quantity<=0 then raise exception 'Invalid quantity'; end if; if p_sold_unit_price<0 then raise exception 'Invalid sold price'; end if; if p_payment_method not in ('cash','mobile_money','card','bank_transfer','other') then raise exception 'Invalid payment method'; end if; select * into v_product from public.products where id=p_product_id and shop_id=p_shop_id for update; if not found then raise exception 'Product not found'; end if; if v_product.status<>'active' or v_product.quantity_on_hand<p_quantity then raise exception 'Insufficient stock'; end if; if v_product.is_unique_piece and p_quantity<>1 then raise exception 'Unique piece quantity must be 1'; end if; insert into public.sales(shop_id,payment_method,total_amount) values(p_shop_id,p_payment_method,p_sold_unit_price*p_quantity) returning id into v_sale_id; insert into public.sale_items(sale_id,product_id,quantity,initial_unit_price,sold_unit_price) values(v_sale_id,p_product_id,p_quantity,v_product.initial_sale_price,p_sold_unit_price); update public.products set quantity_on_hand=quantity_on_hand-p_quantity,status=case when quantity_on_hand-p_quantity=0 then 'sold' else status end where id=p_product_id; return v_sale_id; end; $$;
